package com.ruoyi.medical.persistence;
import com.ruoyi.medical.persistence.mapper.*;
import javax.sql.DataSource;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.*;

/** Explicit N03 deployment only. Missing limits/real authorities fail construction, not open access. */
@Configuration(proxyBeanMethods=false)
@ConditionalOnProperty(name="medical.task-strict-field.enabled",havingValue="true",matchIfMissing=false)
@EnableConfigurationProperties(TaskStrictFieldRuntimePolicy.class)
public class TaskStrictFieldConfiguration {
    @Bean TaskStrictFieldTextEvidence taskStrictFieldTextEvidence(SourceExactMapper rows,SourceExactSchema exact,StrictComparisonCodec codec){return new TaskStrictFieldTextEvidence(rows,exact,codec);}
    @Bean TaskStrictFieldTypedTargetService taskStrictFieldTypedTargetService(EnterpriseAccess access,TaskStrictFieldTypedStore store,StrictComparisonCodec codec,TaskStrictFieldTypedActors actors,TaskFieldTargetBasis tasks,StrictComparisonRunScope scopes,StrictComparisonAuthority authority,StrictDecimalEvidenceService decimals,TaskStrictFieldContextService contexts,StrictComparisonPolicyService policies,StrictFieldComparisonSchema schema,TaskStrictFieldTextEvidence texts,FormalCapabilityIdentityAuthority roles){return new TaskStrictFieldTypedTargetService(access,store,codec,actors,tasks,scopes,authority,decimals,contexts,policies,schema,texts,roles);}
    @Bean TaskStrictFieldTypedTargetLedger taskStrictFieldTypedTargetLedger(@Qualifier("masterDataSource")DataSource data,StrictComparisonCodec codec,ArtifactRegistryMapper registry,DependencyManifestSchema dependencies,DependencyLineage lineage,TaskFieldTargetPolicy bounds,com.ruoyi.medical.identity.IdentityDirectoryPolicy identity,VersionResourceMapper owners){return new TaskStrictFieldTypedTargetLedger(data,codec,registry,dependencies,lineage,bounds,identity,owners);}
    @Bean TaskStrictFieldTypedTargetProducer taskStrictFieldTypedTargetProducer(EnterpriseAccess access,TaskStrictFieldTypedTargetService targets,TaskStrictFieldTypedTargetLedger ledger,@Qualifier("taskFieldTargetTransport")org.springframework.beans.factory.ObjectProvider<RuntimeObjectTransport> transport,StrictComparisonCodec codec,ResourceReadAuthority resources){return new TaskStrictFieldTypedTargetProducer(access,targets,ledger,transport.getIfAvailable(),codec,resources);}
    @Bean TaskStrictFieldTypedStore taskStrictFieldTypedStore(@Qualifier("masterDataSource")DataSource data,StrictComparisonCodec codec,com.ruoyi.medical.identity.IdentityDirectoryPolicy identity)throws Exception{return new TaskStrictFieldTypedStore(data,codec,identity);}
    @Bean TaskStrictFieldTypedActors taskStrictFieldTypedActors(PermissionMapper permissions,PermissionAuthority grants,com.ruoyi.medical.identity.PlatformMemberIdentityStatus identities,ResourceReadAuthority resources,StrictComparisonCodec codec){return new TaskStrictFieldTypedActors(permissions,grants,identities,resources,codec);}
    @Bean TaskStrictFieldContextService taskStrictFieldContextService(EnterpriseAccess access,TaskStrictFieldTypedStore store,StrictComparisonCodec codec,StrictComparisonAuthority authority,SourceReadAuthority sources,TaskFieldSourceAuthority processing,org.springframework.beans.factory.ObjectProvider<SourceUploadTransport> transport,TaskFieldTargetPolicy objects,StrictComparisonRuntimePolicy capacity,TaskStrictFieldTypedActors actors)throws Exception{return new TaskStrictFieldContextService(access,store,codec,authority,sources,processing,transport.getIfAvailable(),objects,capacity,actors);}
    @Bean StrictFieldComparisonSchema strictFieldComparisonSchema()throws Exception{return new StrictFieldComparisonSchema();}
    @Bean TaskStrictFieldSchema taskStrictFieldSchema(TaskFieldTargetSchema targets,StrictFieldComparisonSchema comparison){return new TaskStrictFieldSchema(targets,comparison);}
    @Bean TaskStrictFieldTargetAuthority taskStrictFieldTargetAuthority(@Qualifier("masterDataSource")DataSource data,TaskFieldTargetSchema schema,ArtifactRegistryMapper registry,
            SourceReadAuthority sources,PermissionSchema json,ResourceReadAuthority resources,DependencyManifestSchema dependencies,DependencyLineage lineage,
            @Qualifier("taskRunLineageLimits")DependencyLineage.Limits limits,TaskStrictFieldTypedTargetService typedTargets,TaskStrictFieldTypedTargetLedger typedLedger){return new TaskStrictFieldTargetAuthority(data,schema,registry,sources,json,resources,dependencies,lineage,limits,typedTargets,typedLedger);}
    @Bean TaskStrictFieldInputAuthority taskStrictFieldInputAuthority(@Qualifier("masterDataSource")DataSource data,TaskStrictFieldSchema schema,PermissionSchema json,
            TaskStrictFieldTargetAuthority targets,TaskFieldTargetInputCapabilityService capabilities,TaskRunGraphService graphs,TaskResearchCompletionAuthority completions,
            StrictComparisonRunScope scopes,StrictComparisonPolicyService policies,FormalCapabilityIdentityAuthority roles,FormalRuntimeCapabilityIdentityAuthority tools,
            RunTokenAuthoritySchema tokens,VersionResourceMapper owners,TaskStrictFieldContextService contexts){return new TaskStrictFieldInputAuthority(data,schema,json,targets,capabilities,graphs,completions,scopes,policies,roles,tools,tokens,owners,contexts);}
    @Bean TaskStrictFieldPreparation taskStrictFieldPreparation(@Qualifier("masterDataSource")DataSource data,TaskStrictFieldInputAuthority inputs,TaskStrictFieldMaterializer materializer,TaskStrictFieldTargetAuthority targets,TaskStrictFieldSchema schema,StrictComparisonRunScope scopes,StrictComparisonPolicyService policies,FormalRuntimeCapabilityIdentityAuthority tools,PermissionSchema json){return new TaskStrictFieldPreparation(data,inputs,materializer,targets,schema,scopes,policies,tools,json);}
    @Bean TaskStrictFieldMaterializer taskStrictFieldMaterializer(@Qualifier("masterDataSource")DataSource data,TaskStrictFieldSchema schema,RunTokenAuthoritySchema tokens){return new TaskStrictFieldMaterializer(data,schema,tokens);}
    @Bean TaskStrictFieldSourceReader taskStrictFieldSourceReader(@Qualifier("masterDataSource")DataSource data,TaskStrictFieldSchema schema,PermissionSchema json,
            SourceReadAuthority sources,SourceExactMapper exacts,SourceExactSchema exact,TaskFieldSourceAuthority processing,TaskFieldSourceReader parsedVerifier,
            SourceUploadTransport transport,TaskStrictFieldRuntimePolicy policy,StrictComparisonRunScope scopes,StrictDecimalEvidenceService decimals,TaskStrictFieldContextService contexts,TaskStrictFieldTextEvidence texts){return new TaskStrictFieldSourceReader(data,schema,json,sources,exacts,exact,processing,parsedVerifier,transport,policy.maximumObjectBytes(),scopes,decimals,contexts,texts);}
    @Bean TaskStrictFieldResultRegistration taskStrictFieldResultRegistration(@Qualifier("masterDataSource")DataSource data,TaskStrictFieldSchema schema,StrictFieldComparisonSchema comparison,
            StrictComparisonRunScope scopes,StrictComparisonPolicyService policies,TaskStrictFieldSourceReader sources,TaskStrictFieldRuntimePolicy capacity){return new TaskStrictFieldResultRegistration(data,schema,comparison,scopes,policies,sources,capacity.limits());}
    @Bean TaskStrictFieldOutputLedger taskStrictFieldOutputLedger(@Qualifier("masterDataSource")DataSource data,TaskStrictFieldSchema schema,ArtifactRegistryMapper registry,DependencyManifestSchema dependencies,DependencyLineage lineage,TaskFieldTargetPolicy bounds,VersionResourceMapper owners,TaskStrictFieldSourceReader sources,FormalCapabilityIdentityAuthority roles){return new TaskStrictFieldOutputLedger(data,schema,registry,dependencies,lineage,bounds,owners,sources,roles);}
    @Bean TaskStrictFieldWriterReadAuthority taskStrictFieldWriterReadAuthority(@Qualifier("masterDataSource")DataSource data,TaskStrictFieldOutputLedger outputs,TaskRunStageCommitServiceV2 commits,TaskStrictFieldTargetAuthority targets,StrictComparisonRunScope scopes,StrictComparisonPolicyService policies,TaskStrictFieldSchema schema,ResourceReadAuthority resources,DependencyLineage lineage,VersionResourceAuthority versions,ArtifactRegistryMapper registry,SourceReadMapper sourceRows,SourceReadAuthority sources,EvaluationReferences profiles,TaskFieldTargetPolicy bounds,StrictComparisonStore policyStore,TaskRunResumeOriginalAuthority originals,TaskStrictFieldInputAuthority inputs){return new TaskStrictFieldWriterReadAuthority(data,outputs,commits,targets,scopes,policies,schema,resources,lineage,versions,registry,sourceRows,sources,profiles,bounds,policyStore).withOriginalReaders(originals,inputs);}
    @Bean TaskStrictFieldOutputProducer taskStrictFieldOutputProducer(TaskStrictFieldOutputLedger ledger,@Qualifier("taskFieldTargetTransport")org.springframework.beans.factory.ObjectProvider<RuntimeObjectTransport> transport,TaskStrictFieldSourceReader sources,TaskStrictFieldSchema schema){return new TaskStrictFieldOutputProducer(ledger,transport.getIfAvailable(),sources,schema);}
    @Bean TaskStrictFieldNode taskStrictFieldNode(@Qualifier("masterDataSource")DataSource data,FormalWorkerAccess workers,TaskStrictFieldSchema schema,StrictFieldComparisonSchema comparison,StrictComparisonRunScope scopes,
            StrictComparisonPolicyService policies,TaskStrictFieldSourceReader sources,TaskStrictFieldResultRegistration results,TaskStrictFieldRuntimePolicy capacity,TaskStrictFieldOutputProducer outputs){return new TaskStrictFieldNode(data,workers,schema,comparison,scopes,policies,sources,results,capacity.limits(),outputs);}
    @Bean TaskStrictFieldOriginalResult taskStrictFieldOriginalResult(@Qualifier("masterDataSource")DataSource data,TaskStrictFieldSchema schema,StrictFieldComparisonSchema comparison,StrictComparisonStore policies,StrictComparisonCodec codec,TaskStrictFieldRuntimePolicy capacity,TaskStrictFieldOutputLedger outputs){return new TaskStrictFieldOriginalResult(data,schema,comparison,policies,codec,capacity,outputs);}
    @Bean TaskStrictFieldDispatchReservation taskStrictFieldDispatchReservation(@Qualifier("masterDataSource")DataSource data,TaskStrictFieldInputAuthority inputs,com.ruoyi.medical.identity.ServiceCertificateIdentity services,PermissionSchema json){return new TaskStrictFieldDispatchReservation(data,inputs,services,json);}
    @Bean TaskStrictFieldExecutionBridge taskStrictFieldExecutionBridge(@Qualifier("masterDataSource")DataSource data,TaskRunActivityPreparation preparation,FormalRunRecoveryAccess recovery,TaskStrictFieldDispatchReservation commands,RunTokenAuthority tokens,TaskStrictFieldNode node,TaskStrictFieldCompletionAuthority completions,TaskStrictFieldSchema schema,TaskStrictFieldPreparation strictPreparation,TaskDeterministicExecution executions,org.springframework.core.env.Environment environment){
        return new TaskStrictFieldExecutionBridge(data,preparation,recovery,commands,tokens,node,completions,schema,strictPreparation,java.time.Duration.ofSeconds(environment.getRequiredProperty("medical.task-strict-field.lease-lifetime-seconds",Long.class)),java.time.Duration.ofSeconds(environment.getRequiredProperty("medical.task-strict-field.token-lifetime-seconds",Long.class)),executions);
    }
    @Bean TaskStrictFieldCompletionAuthority taskStrictFieldCompletionAuthority(@Qualifier("masterDataSource")DataSource data,TaskStrictFieldNode node,TaskStrictFieldResultRegistration results,TaskStrictFieldSchema schema,TaskStrictFieldOriginalResult originals,TaskStrictFieldDispatchReservation commands,TaskStrictFieldOutputLedger outputs){return new TaskStrictFieldCompletionAuthority(data,node,results,schema,originals,commands,outputs);}
    @Bean TaskStrictFieldAt05Adapter taskStrictFieldAt05Adapter(TaskStrictFieldNode node){return new TaskStrictFieldAt05Adapter(node);}
}
